import React, { useState } from "react";
import { Link, useLocation } from "react-router-dom";

const Sidebar = ({ role, items, activeItem, onSelect, onLogout }) => {
  const location = useLocation();
  const [open, setOpen] = useState(false);

  const closeMenu = () => setOpen(false);

  const handleSelect = (itemKey) => {
    onSelect(itemKey);
    closeMenu();
  };

  const handleLogout = () => {
    closeMenu();
    onLogout();
  };

  return (
    <>
      <button
        type="button"
        className="menu-toggle"
        aria-label="Open navigation menu"
        aria-expanded={open}
        onClick={() => setOpen(true)}
      >
        <span />
        <span />
        <span />
      </button>

      {open ? <button type="button" className="sidebar-overlay" aria-label="Close navigation menu" onClick={closeMenu} /> : null}

      <aside className={`sidebar ${open ? "open" : ""}`}>
        <div className="brand-card">
          <div className="brand-icon">ER</div>
          <div>
            <h2>ED Reserve</h2>
            <p>{role} dashboard</p>
          </div>
        </div>

        <nav className="sidebar-nav">
          {items.map((item) =>
            item.to ? (
              <Link
                key={item.key}
                to={item.to}
                className={`nav-item ${location.pathname === item.to ? "active" : ""}`}
                onClick={closeMenu}
              >
                <span>{item.icon}</span>
                {item.label}
              </Link>
            ) : (
              <button
                key={item.key}
                type="button"
                className={`nav-item ${activeItem === item.key ? "active" : ""}`}
                onClick={() => handleSelect(item.key)}
              >
                <span>{item.icon}</span>
                {item.label}
              </button>
            )
          )}
        </nav>

        <button type="button" className="logout-button" onClick={handleLogout}>
          Logout
        </button>
      </aside>
    </>
  );
};

export default Sidebar;
